from math import gcd as greatest_common_divisor

def lcm(x, y):
    return (x * y) // greatest_common_divisor(x, y)

def find_max_lcm(n):
    max_lcm = 1
    for i in range(1, n + 1):
        for j in range(i, n + 1):
            if lcm(i, j) > max_lcm:
                max_lcm = lcm(i, j)
    return max_lcm

def calculate_divisors(n):
    divisors = set()
    for i in range(1, int(n ** 0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return len(divisors)

def find_periodic_subarrays(n, a):
    max_lcm = find_max_lcm(n)
    divisors = calculate_divisors(n)
    total_periods = divisors * (n // max_lcm)
    return int(total_periods // n)

