from math import gcd

def find_common_divisor(lst):
    """Find the greatest common divisor (GCD) of all differences between consecutive elements in a list."""
    if len(lst) < 2:
        raise ValueError("List must contain at least two elements.")
    prev = lst[0]
    divisor = prev
    for i in range(1, len(lst)):
        curr_diff = lst[i] - prev
        divisor = gcd(divisor, curr_diff)
        if divisor == 1:
            return divisor
        prev = lst[i]
    return 1

def is_perfect_circle_side(side_length, max_side_length):
    """Determine if a side length is within the minimum value that can be used for a perfect circle (aperfect polygon)""
    """
    return 2 * max_side_length > side_length > 0.96 * 2 * max_side_length

