import math

def is_perfect_polygon(n):
    angles = [math.radians(360/n) * i for i in range(1, n)]
    side_distances = sorted([math.sqrt((angles[i] - angles[(i+1) % n])**2 + (angles[(i+1) % n] - angles[(i-1) % n])**2) for i in range(n)])
