def search_polygon(side_min):
    for num_sides in range(3, side_min + 2):
        angles = [math.radians(360/num_sides) * i for i in range(num_sides)]
        if (math.pi/2 > math.sin(math.degrees(angles[0]))) and all(math.abs(math.sin(math.degrees(angles[i])) - math.sin(math.degrees(angles[(i+1) % num_sides]))) < 1e-6 for i in range(num_sides - 1)):
            return True
    return False

def construct_polygon(num_sides, r):
    angles = [math.radians(360 / num_sides) * i for i in range(num_sides)]
    for i in range(num_sides):
        yield int(float(r) * math.sin(math.degrees(angles[i]))), int(float(0) * math.sin(math.degrees(angles[i])))

