def is_perfect_polygon(n, side_lengths):
    """
    Check if a polygon with n sides where all sides have different lengths and
    the smallest possible for a regular polygon is possible.
    """
    smallest_side = min(side_lengths)
    required_area = (n * (n - 3) / 2) * (smallest_side ** 2)
    for side in sorted(side_lengths):
        if required_area < (n * (n - 3) / 2) * (side ** 2):
            return False
    return True

