from collections import defaultdict

def is_solvable(n, m, A, B):
    # Helper function to check if sorting by a single column is possible
    def check_single(A, B, col):
        sorting = {j: i for i, j in enumerate(range(m))}
        for i in range(n):
            sort_col = A[i][col]
            target = None
            for tgt in range(m):
                if tgt == col:
                    continue
                if target is None:
                    target = sort_col
                if A[i][tgt] < A[i][sort_col]:
                    target = sort_col
            if target is None:
                return False
            B[i][col], B[i][target] = B[i][target], B[i][col]
            B[i][target], B[i][select_sort] = B[i][select_sort], B[i][target]
            select_sort = select_sort if select_sort == B[i][col] else select_sort + 1
        return True

    if m % 2 == 0 or m > 5000:
        return -1

    sorted_by_column = defaultdict(int)
    buffer_dict = defaultdict(int)
    buffer_iter = iter(A)
    col = 0
    while True:
        buf_a = next(buffer_iter)
        buf_b = next(buffer_iter)
        if buf_a == buf_b:
            sorted_by_column[col] += 1
        else:
            for i in range(m):
                if buf_a[i] < buf_b[i]:
                    sorted_by_column[col] += 1
                    buffer_dict[i] = col
                    col += 1
                if buf_a[i] > buf_b[i]:
                    if sorted_by_column[col] == 0:
                        break
                    col -= 1
            if sorted_by_column[col]:
                return -1
            for s, i in sorted(buffer_dict.items(), key=lambda t: t[1]):
                select_sort = s
                break
            for i in range(n):
                B[i][col] = buf_b[i]
                buf_a[i], buf_a[select_sort] = buf_a[select_sort], buf_a[i]
                B[i][select_sort], B[i][col] = B[i][col], B[i][select_sort]
        if sorted_by_column[col] % 2 != 0:
            return -1
        col += 1

        if sorted_by_column[col] % 2:
            return -1
        for i in range(m - 1):
            if buffer_dict[i] != buffer_dict[i + 1]:
                return -1

        # Removal of duplicate columns between cols 1 and (m - 1)
        for i in range(1, m - 1):
            if i in sorted_by_column and sorted_by_column[i] == sorted_by_column[i + 1]:
                sorted_by_column[i] = 0
                sorted_by_column[i + 1] = 0
                if sorted_by_column[col] == 0:
                    col -= 1
                    break
        if col == m - 1:
            break

    return col

