def solve(hussain_multiset: list, queries: list):
    n, m = read_ints()

    heapq.heapify(hussain_multiset)

    for _ in range(m):
        qu = read_ints()[0]

        if len(hussain_multiset) > 1 and qu - 1 < 0:
            heapq.heappush(hussain_multiset, hussain_multiset[0])
            hussain_multiset.pop()

        quotient, remainder = divmod(hussain_multiset[0], 2)
        hussain_multiset[0] = quotient

        if remainder > 0:
            hussain_multiset.remove(remainder)

        print(hussain_multiset[0])

