import sys

def mark_remove_cards(starting_index, direction, remaining_cards, left_card, right_card):
    """
    Marks and removes the card at the starting index from the line of cards, simulating the game's rule.
    :param starting_index: int - the 0-based index of the starting card.
    :param direction: str - the starting direction (left or right).
    :param remaining_cards: int - the number of cards initially.
    :param left_card: (int, int) - coordinates of the left card, represented as (initial_index, index_counter).
    :param right_card: (int, int) - coordinates of the right card, represented as (initial_index, index_counter).
    :return: None
    """
    index_counter = remaining_cards
    current_index = starting_index
    if direction == "left":
        while True:
            current_index -= 1
            index_counter += 1
            if current_index < 0:
                current_index += remaining_cards
            if current_index == left_card[0]:
                break
        left_card = (current_index, index_counter)
    elif direction == "right":
        while True:
            current_index += 1
            index_counter += 1
            if current_index == remaining_cards:
                current_index = 0
            if current_index == right_card[0]:
                break
        right_card = (current_index, index_counter)
    return -(len(right_card[0]) + right_card[1]), -(len(left_card[0]) + left_card[1])

