from collections import deque

def get_last_remaining(n, start_A, direction_A, start_B, direction_B):
    queue = deque([i for i in range(n)])

    while len(queue) > 1:
        if direction_A == 'left':
            if start_A > 0:
                start_A -= 1
        elif direction_A == 'right':
            if start_A < n - 1:
                start_A += 1

        if direction_B == 'left':
            if start_B > 0:
                start_B -= 1
        elif direction_B == 'right':
            if start_B < n - 1:
                start_B += 1

        queue.popleft()
        if start_A != start_B:
            if (start_A > start_B and direction_A == 'left') or (start_A < start_B and direction_A == 'right'):
                queue.append(start_A + 1)
                queue.append(start_B + 1)
            elif (start_A > start_B and direction_B == 'left') or (start_A < start_B and direction_B == 'right'):
                if start_A < start_B:
                    queue.append(start_B + 1)
                    queue.append(start_B + 2)
                else:
                    queue.append(start_A + 1)
                    queue.append(start_A + 2)

        queue.appendleft(queue.pop())

    return queue.pop()

