from collections import defaultdict

def snake_game(n, m, frogs):
    board = defaultdict(int)
    for frog in frogs:
        current_cell = frog[0]
        jump = frog[1]
        while current_cell < m:
            board[current_cell] += 1
            current_cell += jump
    finished = set()
    while n > 0:
        frog_map = {frogs[i][0]: i for i in range(n)}
        for frog in sorted(frogs, key=lambda x: x[1] * frog_map[x[0]], reverse=True):
            target_cell = frog[0] + frog[1]
            removed_frogs = frog_map[target_cell]
            if removed_frogs > 0:
                frog_map[target_cell] -= removed_frogs
                if frog_map[target_cell] == 0:
                    finished.add(frog[1])
        del frog_map
        n -= len(finished)
        frogs = list(filter(lambda x: x[1] not in finished, frogs))
    return sum(x[1] for x in frogs), sorted(x[1] for x in frogs)

