import sys

def sort_tables(n, m):
    a = [list(map(int, input().split())) for _ in range(n)]
    b = [list(map(int, input().split())) for _ in range(n)]
    columns = [i for i in range(1, m + 1)]
    attempts = []

    while True:
        # Attempt to sort by the first column
        if a == b:
            return len(attempts), attempts

        min_idx = columns[0]
        for i in columns:
            if a[0][i] < a[0][min_idx]:
                min_idx = i

        attempts.append(min_idx)
        columns.remove(min_idx)
        for i in range(n):
            for j in range(m):
                if a[i][min_idx] != b[i][min_idx]:
                    a[i].remove(a[i][min_idx])
                    b[i].remove(b[i][min_idx])

def main():
    n, m = map(int, input().split())
    result = sort_tables(n, m)
    if result[0] == -1:
        print(f"{result[0]}")
    else:
        print(result[0])
        print(" ".join(map(str, result[1])))

if __name__ == "__main__":
    sys.setrecursionlimit(10**9)
    main()
