from collections import defaultdict

def find_stayed_frogs(n, m, frogs):
    jump_map = defaultdict(int)
    stay_map = defaultdict(set)
    for _, ai in frogs:
        jump_map[ai] += 1

    def dfs(cell, remain_turns):
        if remain_turns == 0:
            stay_map[cell].add(cell)
        else:
            next_cells = [cell + i for i in range(1, ai + 1)]
            for next_cell in next_cells:
                if 1 <= next_cell <= m:
                    jump_map[ai] -= 1
                    dfs(next_cell, remain_turns - 1)
                    jump_map[ai] += 1

    for ai, jn in jump_map.items():
        dfs(1, jn - 1)

    result = nlargest(1, stay_map.values())
    ans = [frogs[i][1] for i in stay_map[result[0]]]
    return result[0], ans

