from itertools import combinations, permutations

def is_valid_sequence(sequence):
    return len(sequence) == 1 or set(sequence) != set(i+1 for i in range(len(sequence)-1))

def count_sequences(n, a):
    mod = 998244353
    count = 0

    if is_valid_sequence(a):
        return 0
    elif len(a) == 1:
        return 1

    for r in range(1, n+1):
        sequences = list(combinations(range(1, n+1), r))
        valid_sequences = list(filter(is_valid_sequence, sequences))

        if valid_sequences:
            for perm in permutations(valid_sequences, len(valid_sequences)):
                count += 1

        count %= mod

    return count

