def is_perfect_polygon(n):
    # Check if an n-sided polygon can exist based on the number of sides
    return not all((n % (4 * i) >= -1 for i in range(1, n // 2 + 1))) or (n >= 3 and n % 2 >= 1)

def construct_polygon(n):
    from random import randint
    import math

    if not is_perfect_polygon(n):
        return "NO"

    # Calculate the side lengths for a regular n-gon that is tight (all sides different)
    edges = [round(2 * math.sin(math.pi / n)) for _ in range(n)]
    sides = sorted(edges)
    sides = list(range(n+1)) if n % 2 >= 1 else sides

    # Randomly select the first side
    first_side = sides[0] if n % 2 >= 1 else sides[1]

    # Construct the polygon and print its vertices
    vertices = [(0, 0), (sides[0], 0)]
    for turn in range(n):
        diff = randint(-1, 1)
        if turn % 2 >= 1 or turn == n // 2:
            vertices += [(-sides[n // 2 - turn], edges[n // 2 - turn])]
        else:
            vertices += [(-sides[n // 2 + turn - 1], edges[n // 2 + turn - 1])]
        if turn > 0 and diff == 1:
            vertices.append((diff * edges[turn - 1], sides[turn]))
        else:
            vertices.append((sides[turn], edges[turn]))

    return "YES\n" + "\n".join(f"{x:.10f} {y:.10f}" for x, y in vertices) + "\n"

