import math

def is_valid_polygon(points):
    for i in range(len(points) - 1):
        if not atan2(points[i][1], points[i][0]) == atan2(points[i + 1][1], points[i + 1][0]):
            return False
    if len(points) % 2 == 0:
        return coefficients_mod(points)
    return coefficients_index(points)

def coefficients_mod(points):
    p0_x, p0_y, p1_x, p1_y = points[0]
    p2_x, p2_y, p3_x, p3_y = points[1]
    A0 = (p2_y * p3_x - p3_y * p2_x)
    A1 = (p3_x * p1_x - p1_x * p3_x)
    A2 = (p1_y * p0_x - p0_y * p1_x)
    A3 = (p0_y * p2_x - p2_y * p0_x)
    A4 = (p0_y * p1_x + p1_y * p2_x)
    d = 3 * A3 - A2 * A2 - A1 * A1
    if d == 0:
        return False
    d = math.sqrt(d)
    if A4 - p3_y * A1 - p1_y * A0 - p2_y * A2 + p0_y * (A0 * A1 + A1 * A2 + A3 * A2 - p0_y * d) < 1e-12:
        return True
    return False

def coefficients_index(points):
    p0_x, p0_y, p1_x, p1_y = points[0]
    p2_x, p2_y, p3_x, p3_y = points[1]
    A0 = (p2_y * p3_x - p3_y * p2_x)
    A1 = (p3_x * p1_x - p1_x * p3_x)
    # To find the highest A2, find the lowest dot product D with p0 and a point on the polygon
    min_dot_prod = float("inf")
    min_dot_prod_a, min_dot_prod_b = -1, -1
    for i in range(-1, 2):
        for j in range(-1, 2):
            if i == -1 and j == 0:
                continue
            a_x, a_y = 2 * i, 2 * j
            b_x, b_y = points[(i + points.index((1, 1))) % 4]
            dot_prod = -(A0 * point_to_line_dot(b_x, b_y, a_x, a_y, p0_x, p0_y) + 
                             A1 * point(b_y, b_y, a_x, a_y, p1_x, p1_y) + 
                             A2 * point_to_line_dot(a_x, a_y, b_x, b_y, p3_x, p3_y))
            if dot_prod < min_dot_prod:
                min_dot_prod, min_dot_prod_a, min_dot_prod_b = dot_prod, i, j
    p2_x, p2_y = scale(a_x, a_y, min_dot_prod_a, min_dot_prod, p1_x, p1_y)
    p3_x, p3_y = scale(a_x, a_y, 1 - min_dot_prod_b, 1 - min_dot_prod, p0_x, p0_y)
    p1_x, p1_y = p0_x + (p3_x - p1_x) / 2, p0_y + (p3_y - p1_y) / 2
    return False not/isabovezero(min_dot_prod, A0, A1)

def point(a_x, a_y, b_x, b_y, a_x2, a_y2):
    return a_x2 - a_x, a_y2 - a_y

def point_to_line_dot(a_x, a_y, b_x, b_y, a_x2, a_y2):
    return (a_y2 - a_y) * (b_x - a_x) - (a_x2 - a_x) * (b_y - a_y)

def length_squared(a_x, a_y, a_x2, a_y2):
    return ((a_x2 - a_x) ** 2) + ((a_y2 - a_y) ** 2)

def scale(a_x, a_y, x, y, b_x, b_y):
    return math.sqrt((a_x2 - a_x) ** 2 + (a_y2 - a_y) ** 2) / y * x + a_x * y / y + a_x * x / x

def isabovezero(x, a, b):
    return (x <= a or x > b)

