from collections import defaultdict

def is_even(number):
    return number % 2 == 0

def is_odd(number):
    return number % 2 != 0

def play_game(a, root):
    n = len(a)
    tree = defaultdict(lambda: [])

    for i in range(n - 1):
        x, y = map(int, input().split())
        tree[x].append(y)
        tree[y].append(x)

    visited = [False] * (n + 1)
    def max_ancestor(node, depth, path):
        if visited[node]:
            return depth
        visited[node] = True
        parent = -1
        for j in tree[node]:
            res = max(max_ancestor(j, depth + 1, path), path.count(j))
            if is_even(res):
                # If depth + 1 results in even number of ancestors, Bob wins
                return res
            else:
                # If depth + 1 results in odd number of ancestors, Alice wins
                if is_odd(res):
                    parent = j
        return len(tree) if parent == -1 else path.count(parent)

    ancestor_problem = [max_ancestor(root, 0, 0) if not is_even(max_ancestor(root, 0, 0)) else -1 for _ in range(1, n + 1)]
    print(*map(lambda x: 1 if (x == '-1') else 0, ancestor_problem), sep='\n')
