import sys

def find_sorting_order(A, B):
    n, m = len(A), len(A[0])
    augmented_memo = {(i, (0, e)): [i] for i, e in enumerate(A)}

    for i in range(m):
        augmented_memo[(0, (size, e))].append(i)

    queue = [(0, 0, (0, 0))]

    while queue:
        iter_index, num_operations, memo = queue.pop()

        size, element = memo

        if size == n:
            return num_operations

        for _, next_sorted_order in augmented_memo.get((iter_index, memo), {}):
            if element != next_sorted_order:
                queue.append((next_sorted_order, num_operations + 1, (size + 1, next_sorted_order)))

    return -1

# Read input
