from functools import lru_cache

def count_arrangements(n, limits):
    if n <= 1:
        return 1

    p = [0] * (n+1)
    p[1] = 1
    limit = {v: i for i, v in enumerate(sorted(limits))}

    @lru_cache(None)
    def dp(i, tripped):
        if i == 0:
            return ((1 << limit[tripped]) - 1)
        count = 0
        for n_to_flip in range(i + 1):
            if n_to_flip > p[n_to_flip]:
                break
            flip_type = tripped if p[n_to_flip] else (limit[tripped] - n_to_flip)
            flip_value = limit[flip_type if n_to_flip < p[n_to_flip] else tripped]
            flip_pos = limit.get(flip_value, p[n_to_flip])
            count += 1 << flip_pos
        return count

    for i in range(2, n + 1):
        p[i] = p[i - 1] ^ (1 << tripped) for tripped in range(1, n + 1)

    return dp(n, 1)

